insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'a8e596a3-b992-52b0-8024-7926869de66f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S1.1' limit 1), 'S1.1 Introduction to the particulate nature of matter · Lesson 1: Elements, compounds and mixtures; separation; kinetic molecular theory; temperature', 'IB DP Chemistry · S1.1 Introduction to the particulate nature of matter', '/chem-s11-lesson1/', 'CHEM-S11-L1', 23, 1 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S11-L1', 'S1.1 Introduction to the particulate nature of matter · Lesson 1: Elements, compounds and mixtures; separation; kinetic molecular theory; temperature', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Compound", "Element", "Homogeneous mixture", "Heterogeneous mixture", "Compound", "Homogeneous mixture"], "tip": "Fixed ratio and bonded = compound."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Simple distillation", "Evaporation/crystallization", "Filtration", "Chromatography", "Fractional distillation"], "tip": "What property differs?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["dissolve", "water", "solvation"], ["filter", "filtration", "sand"], ["evaporat", "crystal", "heat"]], "tips": ["Dissolve, separate, recover."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Sublimation", "Deposition", "298 K", "373 K", "−273 °C"], "tip": "Add 273."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["energy", "heat"], ["overcome", "break", "forces", "attraction", "not increase kinetic"]], "tips": ["Where does the energy go?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["compound+fixed", "compound+bonded", "compound+chemically"], ["mixture+not", "mixture+physical", "mixture+no fixed"]], "tips": ["Ratio, bonding, separation."]}]}, "models": {"1": [["Q1", "NaCl and water: compounds. Copper: element. Air and brass: homogeneous mixtures. Sand and water: heterogeneous."]], "2": [["Q2", "Seawater: simple distillation. Salt: evaporation. Sand: filtration. Ink dyes: chromatography. Ethanol–water: fractional distillation."], ["Q3", "Add water and stir so the salt dissolves [1]; filter to remove the insoluble sand as residue [1]; evaporate the filtrate until crystals form, then dry them [1]."]], "3": [["Q4", "Sublimation; deposition; 298 K; 373 K; −273 °C."], ["Q5", "The energy supplied is used to overcome the attractive forces between the water molecules [1] rather than to increase their average kinetic energy, so the temperature stays constant [1]."]], "4": [["Q6", "A compound contains elements chemically bonded in a fixed ratio and can only be separated by chemical reactions [1]; a mixture contains substances not chemically bonded, in no fixed ratio, and can be separated by physical methods [1]."]], "6": [["Exit ticket", "It is proportional to the average kinetic energy of the particles."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5aa007d8-bb4d-5fc9-9090-43aa1e584a6b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S1.2' limit 1), 'S1.2 The nuclear atom · Lesson 1: Subatomic particles, nuclear symbols, isotopes and relative atomic mass', 'IB DP Chemistry · S1.2 The nuclear atom', '/chem-s12-lesson1/', 'CHEM-S12-L1', 14, 2 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S12-L1', 'S1.2 The nuclear atom · Lesson 1: Subatomic particles, nuclear symbols, isotopes and relative atomic mass', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["11", "12", "10", "18", "19"], "tip": "Neutrons = A − Z; adjust electrons for charge."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["same electron", "electron configuration", "same number of electrons"], ["mass", "neutrons", "density"]], "tips": ["Electrons vs neutrons."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["24.3", "63.6", "10.8"], "tip": "Σ(mass × %) ÷ 100."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["69x", "69 x", "x +", "100 − x", "100-x"], ["64", "64%"]], "tips": ["Let ⁶⁹Ga = x%."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["26 protons", "26 p", "p = 26", "protons: 26"], ["30", "23"]], "tips": ["A − Z; subtract 3 electrons."]}]}, "models": {"1": [["Q1", "²³Na: 11 protons, 12 neutrons; Na⁺: 10 electrons; S²⁻: 18 electrons; ³⁶Cl: 36 − 17 = 19 neutrons."]], "2": [["Q2", "Isotopes have the same number of electrons and electron configuration, so they react in the same way [1]; they have different numbers of neutrons and so different masses, giving different densities and rates of diffusion [1]."]], "3": [["Q3", "Mg: (24×79 + 25×10 + 26×11)/100 = 24.32. Cu: (63×69.2 + 65×30.8)/100 = 63.6. B: (10×20 + 11×80)/100 = 10.8."], ["Q4", "69x + 71(100 − x) = 6972 [1]; 7100 − 2x = 6972, so x = 64, i.e. 64% ⁶⁹Ga [1]."]], "4": [["Q5", "26 protons [1]; 30 neutrons and 23 electrons [1]."]], "6": [["Exit ticket", "Atoms of the same element with the same number of protons but different numbers of neutrons."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6b9cdf3d-f72c-5ec6-851a-75c1d35ef728', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S1.3' limit 1), 'S1.3 Electron configurations · Lesson 1: Emission spectra, energy levels, sublevels, orbitals and electron configurations', 'IB DP Chemistry · S1.3 Electron configurations', '/chem-s13-lesson1/', 'CHEM-S13-L1', 14, 3 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S13-L1', 'S1.3 Electron configurations · Lesson 1: Emission spectra, energy levels, sublevels, orbitals and electron configurations', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["excited", "absorb", "higher level"], ["fall", "drop", "return", "photon"], ["specific", "discrete", "only certain", "fixed"]], "tips": ["Excite, fall, specific lines."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["18", "10", "2", "6", "14"], "tip": "2n²; s2 p6 d10 f14."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["[Ne] 3s² 3p⁴", "[Ar] 4s¹ 3d⁵", "[Ar] 4s¹ 3d¹⁰", "[Ar] 3d⁶"], "tip": "Watch Cr and Cu; ions lose 4s first."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["energy levels", "levels"], ["closer", "converge", "smaller difference"]], "tips": ["Spacing of levels."]}]}, "models": {"1": [["Q1", "Electrons absorb energy and move to higher energy levels [1]; when they fall back they emit photons whose energy equals the difference between levels [1]; only specific frequencies (lines) are seen, so only certain energy levels are allowed [1]."]], "2": [["Q2", "18; 10; 2; 6; 14."]], "3": [["Q3", "S: [Ne] 3s² 3p⁴. Cr: [Ar] 4s¹ 3d⁵. Cu: [Ar] 4s¹ 3d¹⁰. Fe²⁺: [Ar] 3d⁶."], ["Q4", "1s ↑↓, 2s ↑↓, 2p ↑ ↑ ↑ — the three 2p electrons occupy separate orbitals with parallel spins before any pairing (Hund''s rule)."]], "4": [["Q5", "The energy levels get closer together as n increases (further from the nucleus) [1], so the energy differences between transitions, and hence the frequencies of the lines, get closer together [1]."]], "6": [["Exit ticket", "[Ar] 4s¹ 3d¹⁰."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b665badf-f36c-5ccc-b214-246b2212e164', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S1.3' limit 1), 'S1.3 Electron configurations · Lesson 2 (HL): Mass spectra, the convergence limit and successive ionization energies', 'IB DP Chemistry · S1.3 Electron configurations', '/chem-s13-lesson2/', 'CHEM-S13-L2', 11, 4 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S13-L2', 'S1.3 Electron configurations · Lesson 2 (HL): Mass spectra, the convergence limit and successive ionization energies', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["2", "107.96", "Silver"], "tip": "(107×52 + 109×48)/100."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["convergence", "lines merge", "limit"], ["n = 1", "infinity", "removed", "ionization", "hf"]], "tips": ["Where the lines meet."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 2, "n": 2, "ans": ["3", "Group 13"], "tip": "Where is the big jump?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["inner", "new", "lower", "second shell", "n = 2"], ["closer", "less shield", "attraction", "nucleus"]], "tips": ["Which shell is the second electron in?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["positive", "ion", "charge"], ["attract", "fewer electrons", "repulsion", "harder"]], "tips": ["Ion charge."]}]}, "models": {"1": [["Q1", "Two isotopes; A_r = (107×52 + 109×48)/100 = 107.96; silver (A_r 107.87)."]], "2": [["Q2", "Find the frequency at which the lines in the Lyman series converge (the convergence limit) [1]; this corresponds to an electron moving from n = 1 to n = ∞ (removal), so IE = hf × N_A [1]."]], "3": [["Q3", "Big jump between the 3rd and 4th IE, so 3 valence electrons: group 13 (aluminium)."], ["Q4", "The second electron is removed from an inner energy level (n = 2) [1], which is closer to the nucleus and less shielded, so it is more strongly attracted and much harder to remove [1]."]], "4": [["Q5", "Each electron is removed from an increasingly positive ion [1], so the remaining electrons are more strongly attracted to the nucleus (and repel each other less), making removal harder [1]."]], "6": [["Exit ticket", "The next electron is being removed from a new, inner energy level."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '9617164e-3f3a-559f-b919-fb4a6969b776', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S1.4' limit 1), 'S1.4 Counting particles by mass: The mole · Lesson 1: The mole, molar mass, empirical formulas, concentration and Avogadro''s law', 'IB DP Chemistry · S1.4 Counting particles by mass: The mole', '/chem-s14-lesson1/', 'CHEM-S14-L1', 13, 5 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S14-L1', 'S1.4 Counting particles by mass: The mole · Lesson 1: The mole, molar mass, empirical formulas, concentration and Avogadro''s law', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.500 mol", "88.0 g", "3.01 × 10²³", "9.03 × 10²³"], "tip": "n = m/M; N = n × N_A; CO₂ has 3 atoms."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["CH₂O", "30", "C₆H₁₂O₆"], "tip": "C 40/12 = 3.33, H 6.7/1 = 6.7, O 53.3/16 = 3.33."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["0.250 mol dm⁻³", "0.0250 mol", "4.0 g", "50 cm³"], "tip": "Convert cm³ to dm³."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["0.100", "0.1 mol"], ["1.20 × 10", "1.2 × 10", "1.20e23", "1.20 x 10"]], "tips": ["Moles, ×2, ×N_A."]}]}, "models": {"1": [["Q1", "0.500 mol; 88.0 g; 3.01 × 10²³ molecules; 0.500 × 3 × 6.02 × 10²³ = 9.03 × 10²³ atoms."]], "2": [["Q2", "Ratio 1 : 2 : 1 → CH₂O (mass 30); 180 ÷ 30 = 6 → C₆H₁₂O₆."]], "3": [["Q3", "0.0500/0.200 = 0.250 mol dm⁻³; 0.0250 mol; 0.100 mol × 40 = 4.0 g; 2 × 25 = 50 cm³."]], "4": [["Q4", "n(CO₂) = 4.40 ÷ 44.01 = 0.100 mol [1]; O atoms = 0.100 × 2 × 6.02 × 10²³ = 1.20 × 10²³ [1]."]], "6": [["Exit ticket", "n = m ÷ M."]]}, "labels": {"q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd0a5d3f9-42c0-509e-8f65-59472887abe6', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S1.5' limit 1), 'S1.5 Ideal gases · Lesson 1: Ideal gas model, real gases, molar volume, gas laws and pV = nRT', 'IB DP Chemistry · S1.5 Ideal gases', '/chem-s15-lesson1/', 'CHEM-S15-L1', 12, 6 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S15-L1', 'S1.5 Ideal gases · Lesson 1: Ideal gas model, real gases, molar volume, gas laws and pV = nRT', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["high pressure+volume", "volume+particles", "close together"], ["low temperature+forces", "intermolecular", "slow", "attraction"]], "tips": ["Volume and forces."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["0.500 mol", "11.4 dm³", "200 kPa", "600 K"], "tip": "22.7 dm³ mol⁻¹; Kelvin."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["nrt", "0.200 × 8.31 × 300", "pv = nrt", "v = nrt/p"], ["3.32", "3.3 dm", "0.00332"]], "tips": ["V = nRT/p, then convert m³ to dm³."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["0.0101", "1.01 × 10", "n = pv/rt", "pv/rt"], ["49.6", "49.5", "50"]], "tips": ["n = pV/RT, then M = m/n."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["negligible volume", "no volume"], ["no intermolecular", "no forces", "elastic", "random"]], "tips": ["Volume and forces."]}]}, "models": {"1": [["Q1", "At high pressure particles are close together, so their own volume is no longer negligible [1]; at low temperature particles move slowly, so intermolecular forces of attraction become significant [1]."]], "2": [["Q2", "0.500 mol; 11.4 dm³; 200 kPa; 600 K."]], "3": [["Q3", "V = nRT/p = 0.200 × 8.31 × 300 ÷ 150 000 [1] = 3.32 × 10⁻³ m³ = 3.32 dm³ [1]."], ["Q4", "n = pV/RT = (100 000 × 2.50 × 10⁻⁴) ÷ (8.31 × 298) = 0.0101 mol [1]; M = 0.500 ÷ 0.0101 = 49.6 g mol⁻¹ [1]."]], "4": [["Q5", "Gas particles have negligible volume [1]; there are no intermolecular forces and collisions are perfectly elastic [1]."]], "6": [["Exit ticket", "22.7 dm³ mol⁻¹ (at 273 K and 100 kPa)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ba122da2-3e1b-5da6-a6f8-f37c062cf337', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S2.1' limit 1), 'S2.1 The ionic model · Lesson 1: Ions, ionic bonding, formulas, lattices and properties of ionic compounds', 'IB DP Chemistry · S2.1 The ionic model', '/chem-s21-lesson1/', 'CHEM-S21-L1', 18, 7 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S21-L1', 'S2.1 The ionic model · Lesson 1: Ions, ionic bonding, formulas, lattices and properties of ionic compounds', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["+2", "−3", "+3", "−2", "+1", "−3"], "tip": "Group number and polyatomic ions."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["MgCl₂", "Al₂O₃", "Ca(NO₃)₂", "(NH₄)₂SO₄", "Na₂CO₃"], "tip": "Balance charges."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["solid+fixed", "solid+cannot move", "fixed position"], ["molten+free", "molten+move", "mobile ions", "ions are free"]], "tips": ["Moving charged particles."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["2+", "2−", "charge", "higher charge"], ["smaller", "radius", "radii"], ["stronger", "attraction", "lattice enthalpy"]], "tips": ["Charge and size."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["layer", "shift", "displace", "force"], ["like charges", "same charge", "repel"]], "tips": ["What happens when the lattice is pushed?"]}]}, "models": {"1": [["Q1", "Mg²⁺; N³⁻; Al³⁺; SO₄²⁻; NH₄⁺; PO₄³⁻."]], "2": [["Q2", "MgCl₂; Al₂O₃; Ca(NO₃)₂; (NH₄)₂SO₄; Na₂CO₃."]], "3": [["Q3", "In the solid, the ions are held in fixed positions in the lattice and cannot move [1]; when molten, the ions are free to move and carry charge [1]."], ["Q4", "Mg²⁺ and O²⁻ have higher charges than Na⁺ and Cl⁻ [1]; the ions are also smaller (smaller radii) [1]; so the electrostatic attraction (lattice enthalpy) is much stronger and more energy is needed to melt it [1]."]], "4": [["Q5", "A force shifts layers of ions in the lattice [1], bringing ions of like charge next to each other, which repel and the crystal shatters [1]."]], "6": [["Exit ticket", "Ca₃(PO₄)₂."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
