insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S22-L1', 'S2.2 The covalent model · Lesson 1: Covalent bonds, Lewis formulas, VSEPR shapes and polarity', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["1", "2", "3", "0", "1"], "tip": "Draw the Lewis formulas."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Linear", "Trigonal planar", "Trigonal pyramidal", "Bent (V-shaped)", "Tetrahedral"], "tip": "Count domains and lone pairs."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["lone pair", "two lone"], ["repel more", "greater repulsion", "push", "more repulsion"]], "tips": ["Lone pairs vs bonding pairs."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Polar", "Non-polar", "Polar", "Non-polar", "Polar"], "tip": "Do the dipoles cancel?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["linear", "symmetric"], ["cancel", "no net dipole", "opposite"]], "tips": ["Shape."]}]}, "models": {"1": [["Q1", "NH₃: 1 lone pair. H₂O: 2. N₂: triple bond, 3 shared pairs. CH₄: 0. NH₄⁺: 1 coordination bond."]], "2": [["Q2", "Linear; trigonal planar; trigonal pyramidal; bent; tetrahedral."], ["Q3", "Water has two lone pairs on oxygen [1]; lone pairs repel more strongly than bonding pairs, pushing the O–H bonds closer together [1]."]], "3": [["Q4", "H₂O, NH₃, CHCl₃: polar. CO₂, CCl₄: non-polar (symmetrical)."]], "4": [["Q5", "CO₂ is linear (symmetrical) [1], so the two C=O bond dipoles point in opposite directions and cancel, giving no net dipole [1]."]], "6": [["Exit ticket", "Trigonal pyramidal, about 107°."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8cdc260e-a335-53b5-a910-f3b8dcd4f87b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S2.2' limit 1), 'S2.2 The covalent model · Lesson 2: Covalent networks, intermolecular forces and chromatography', 'IB DP Chemistry · S2.2 The covalent model', '/chem-s22-lesson2/', 'CHEM-S22-L2', 19, 9 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S22-L2', 'S2.2 The covalent model · Lesson 2: Covalent networks, intermolecular forces and chromatography', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Graphite", "Diamond", "Graphene", "Fullerene C₆₀", "Silicon dioxide"], "tip": "One each."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["London forces", "Dipole–dipole", "Hydrogen bonding", "Hydrogen bonding", "London forces", "Dipole–dipole"], "tip": "H on N, O, F?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["hydrogen bond"], ["h2s+dipole", "h2s+london", "sulfur", "weaker"], ["more energy", "stronger", "overcome"]], "tips": ["Type of IMF in each."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["0.75", "0.25", "Spot B"], "tip": "R_F = distance of spot ÷ distance of solvent."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["graphite+delocal", "graphite+three", "graphite+free electron"], ["diamond+four", "diamond+no free", "diamond+all"]], "tips": ["Bonds per carbon."]}]}, "models": {"1": [["Q1", "Graphite; diamond; graphene; fullerene; silicon dioxide."]], "2": [["Q2", "CH₄ and I₂: London. HCl and CH₃OCH₃: dipole–dipole. H₂O and NH₃: hydrogen bonding."], ["Q3", "Water molecules form hydrogen bonds because H is bonded to the very electronegative O [1]; H₂S has only dipole–dipole and London forces, which are weaker [1]; more energy is needed to overcome the hydrogen bonds in water [1]."]], "3": [["Q4", "A: 6.0/8.0 = 0.75; B: 2.0/8.0 = 0.25; B moves less, so it is more attracted to the stationary phase."]], "4": [["Q5", "In graphite each carbon bonds to three others, leaving one delocalized electron per atom that can move and carry charge [1]; in diamond all four outer electrons are used in bonds, so there are no free electrons [1]."]], "6": [["Exit ticket", "London < dipole–dipole < hydrogen bonding (for comparable molar mass)."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'cf920e34-dd10-50aa-b6f1-8deda5253758', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S2.2' limit 1), 'S2.2 The covalent model · Lesson 3 (HL): Resonance, benzene, expanded octets, formal charge, sigma and pi bonds, hybridization', 'IB DP Chemistry · S2.2 The covalent model', '/chem-s22-lesson3/', 'CHEM-S22-L3', 18, 10 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S22-L3', 'S2.2 The covalent model · Lesson 3 (HL): Resonance, benzene, expanded octets, formal charge, sigma and pi bonds, hybridization', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["same length", "equal length", "139"], ["hydrogenation", "substitution", "less exothermic", "stable", "addition"]], "tips": ["Bond lengths and reactivity/energy."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Trigonal bipyramidal", "Octahedral", "Seesaw", "Square planar", "Linear"], "tip": "Count domains; lone pairs go equatorial in 5-domain shapes."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 2, "n": 2, "ans": ["0", "0"], "tip": "FC = V − N − B/2."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["sp³", "sp²", "sp", "5", "2"], "tip": "Count electron domains."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["sigma+head-on", "sigma+axis", "sigma+end-on", "sigma+between"], ["pi+sideways", "pi+above", "pi+p orbital", "pi+parallel"]], "tips": ["How the orbitals overlap."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["resonance", "delocal"], ["same", "equal", "spread", "intermediate", "1.33"]], "tips": ["Where is the double bond?"]}]}, "models": {"1": [["Q1", "All C–C bonds in benzene have the same length, intermediate between single and double [1]; benzene undergoes substitution rather than addition, and its enthalpy of hydrogenation is less exothermic than predicted, showing extra stability [1]."]], "2": [["Q2", "PCl₅ trigonal bipyramidal; SF₆ octahedral; SF₄ seesaw; XeF₄ square planar; XeF₂ linear."], ["Q3", "C: 4 − 0 − 8/2 = 0; O: 6 − 4 − 4/2 = 0. All zero, so this is the preferred structure."]], "3": [["Q4", "Ethane sp³; ethene sp²; ethyne sp; ethene 5 σ (4 C–H + 1 C–C); ethyne 2 π."], ["Q5", "A sigma bond forms by head-on overlap of orbitals, with electron density along the bond axis [1]; a pi bond forms by sideways overlap of p orbitals, with electron density above and below the axis [1]."]], "4": [["Q6", "The carbonate ion has resonance: the π electrons are delocalized over all three C–O bonds [1], so each bond is identical, intermediate between a single and double bond (bond order 1⅓) [1]."]], "6": [["Exit ticket", "sp²."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '85a29179-f76c-5941-8604-9ca7efa25d3d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S2.3' limit 1), 'S2.3 The metallic model · Lesson 1: Metallic bonding, properties of metals and bond strength', 'IB DP Chemistry · S2.3 The metallic model', '/chem-s23-lesson1/', 'CHEM-S23-L1', 6, 11 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S23-L1', 'S2.3 The metallic model · Lesson 1: Metallic bonding, properties of metals and bond strength', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["layers", "slide", "cations"], ["delocal", "electrons", "not broken", "still attract"]], "tips": ["Layers and electrons."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 2, "n": 2, "ans": ["Magnesium", "Lithium"], "tip": "Charge up, radius down."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["3+", "charge", "three electrons", "more delocalized"], ["smaller", "radius", "stronger"]], "tips": ["Charge and radius."]}]}, "models": {"1": [["Q1", "Layers of cations can slide over each other when a force is applied [1]; the delocalized electrons move with them, so the metallic bonding is not broken [1]."]], "2": [["Q2", "Magnesium (2+ ions, more delocalized electrons, smaller); lithium (smaller ions)."]], "3": [["Q3", "Aluminium forms 3+ ions and contributes three delocalized electrons per atom, compared with 1+ for sodium [1]; Al³⁺ is also smaller, so the electrostatic attraction is stronger [1]."]], "6": [["Exit ticket", "The electrostatic attraction between a lattice of cations and delocalized electrons."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5f69899e-636e-5b24-81e4-bf140f268eae', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S2.4' limit 1), 'S2.4 From models to materials · Lesson 1: The bonding triangle, alloys and addition polymers', 'IB DP Chemistry · S2.4 From models to materials', '/chem-s24-lesson1/', 'CHEM-S24-L1', 11, 12 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S24-L1', 'S2.4 From models to materials · Lesson 1: The bonding triangle, alloys and addition polymers', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Mainly ionic", "Polar covalent", "Metallic"], "tip": "Δχ high → ionic."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["different size", "different-sized", "atoms"], ["disrupt", "layers", "slide", "harder to slide"]], "tips": ["Layers."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Poly(ethene)", "PVC (poly(chloroethene))", "Poly(propene)", "PTFE (poly(tetrafluoroethene))"], "tip": "Name the monomer."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["double bond", "c=c", "breaks"], ["join", "chain", "no other product", "only product"]], "tips": ["Bond broken; product."]}]}, "models": {"1": [["Q1", "NaCl: ionic; SiO₂: polar covalent; Al: metallic."]], "2": [["Q2", "The added atoms are a different size from the metal atoms [1], so they disrupt the regular layers and make it harder for layers to slide over each other [1]."]], "3": [["Q3", "Poly(ethene); PVC; poly(propene); PTFE."]], "4": [["Q4", "The C=C double bond in each monomer breaks [1], and monomers join to form a long chain with no other product formed [1]."]], "6": [["Exit ticket", "Electronegativity difference against average electronegativity."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '66801884-e098-5b7d-8cd1-279084949b1d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S2.4' limit 1), 'S2.4 From models to materials · Lesson 2 (HL): Transition metals'' delocalized d-electrons and condensation polymers', 'IB DP Chemistry · S2.4 From models to materials', '/chem-s24-lesson2/', 'CHEM-S24-L2', 8, 13 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S24-L2', 'S2.4 From models to materials · Lesson 2 (HL): Transition metals'' delocalized d-electrons and condensation polymers', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["d-electron", "d electrons", "3d"], ["more delocal", "stronger", "more electrons"]], "tips": ["Which electrons are delocalized?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Polyamide (amide link)", "Polyester (ester link)", "Addition polymer", "Polyamide (amide link)"], "tip": "What functional groups react?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["double bond", "c=c", "functional group"], ["small molecule", "water", "byproduct", "by-product", "only product"]], "tips": ["Monomers and products."]}]}, "models": {"1": [["Q1", "In iron, 3d electrons as well as 4s electrons are delocalized [1], so there are more delocalized electrons and stronger metallic bonding than in calcium [1]."]], "2": [["Q2", "Diamine + diacid: polyamide; diol + diacid: polyester; propene: addition; amino acids: polyamide."]], "3": [["Q3", "Addition polymers form from monomers with C=C double bonds, whereas condensation polymers form from monomers with two functional groups [1]; condensation releases a small molecule such as water, while addition polymerization forms only the polymer [1]."]], "6": [["Exit ticket", "Water."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd1f35d79-7ef7-5f43-b5d6-4514af808475', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S3.1' limit 1), 'S3.1 The periodic table: Classification of elements · Lesson 1: Periods, groups, blocks, periodic trends, group 1 and 17, oxides and oxidation states', 'IB DP Chemistry · S3.1 The periodic table: Classification of elements', '/chem-s31-lesson1/', 'CHEM-S31-L1', 23, 14 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S31-L1', 'S3.1 The periodic table: Classification of elements · Lesson 1: Periods, groups, blocks, periodic trends, group 1 and 17, oxides and oxidation states', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Period 3", "Group 17", "p-block"], "tip": "Highest n = period; valence electrons → group."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Na", "Li", "Cl", "F⁻"], "tip": "Nuclear charge vs shielding."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["nuclear charge", "protons", "increase"], ["same shell", "same energy level", "shielding", "attract", "pulled"]], "tips": ["Charge vs shielding."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Reaction", "No reaction", "Reaction", "No reaction"], "tip": "More reactive halogen displaces less reactive halide."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["further", "more shells", "larger", "shield"], ["lost more easily", "lower ionization", "weaker attraction", "easier to lose"]], "tips": ["Distance of outer electron."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["+6", "+5", "+7", "−1", "−1", "0"], "tip": "Sum = overall charge."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["na2o", "naoh"], ["so3", "h2so4"]], "tips": ["Each oxide + water."]}]}, "models": {"1": [["Q1", "Period 3, group 17, p-block (chlorine)."]], "2": [["Q2", "Na larger; Li higher IE; Cl more electronegative; F⁻ larger (fewer protons for the same electrons)."], ["Q3", "Nuclear charge increases across the period [1] while electrons are added to the same energy level with similar shielding, so outer electrons are pulled closer to the nucleus [1]."]], "3": [["Q4", "Cl₂ + Br⁻ and Br₂ + I⁻ react; I₂ + Cl⁻ and Br₂ + Cl⁻ do not."], ["Q5", "Potassium''s outer electron is further from the nucleus and more shielded [1], so it is less strongly attracted and lost more easily (lower ionization energy) [1]."]], "4": [["Q6", "+6; +5; +7; −1; −1; 0."]], "5": [["Q7", "Na2O(s) + H2O(l) → 2NaOH(aq) [1]; SO3(g) + H2O(l) → H2SO4(aq) [1]."]], "6": [["Exit ticket", "It decreases, because the bonding electrons are further from the nucleus and more shielded."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '347dd2f6-8777-53b0-a641-c782855b645a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S3.1' limit 1), 'S3.1 The periodic table: Classification of elements · Lesson 2 (HL): Ionization energy discontinuities and transition elements', 'IB DP Chemistry · S3.1 The periodic table: Classification of elements', '/chem-s31-lesson2/', 'CHEM-S31-L2', 13, 15 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S31-L2', 'S3.1 The periodic table: Classification of elements · Lesson 2 (HL): Ionization energy discontinuities and transition elements', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["3p"], ["higher energy", "further", "shield", "easier"]], "tips": ["Which sublevel?"]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["paired", "pair", "same orbital", "doubly"], ["repulsion", "repel", "easier"]], "tips": ["Orbital diagram of 3p."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["[Ar] 3d⁵", "[Ar] 3d⁹", "[Ar] 3d³", "[Ar] 3d¹⁰"], "tip": "Remove 4s first."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["split", "ligand"], ["absorb", "promot", "photon"], ["complementary", "orange", "red", "transmit", "observed"]], "tips": ["Split, absorb, observe."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["3d10", "full", "complete"], ["no d-d", "cannot", "no transition", "no electron can"]], "tips": ["Configuration of Zn²⁺."]}]}, "models": {"1": [["Q1", "Aluminium''s outer electron is in a 3p sublevel, whereas magnesium''s is in 3s [1]; the 3p electron is higher in energy (and partly shielded by 3s), so it is easier to remove [1]."], ["Q2", "In sulfur, the electron removed is from a 3p orbital containing a pair of electrons [1]; repulsion between the paired electrons makes it easier to remove [1]."]], "2": [["Q3", "Fe³⁺ [Ar] 3d⁵; Cu²⁺ [Ar] 3d⁹; Cr³⁺ [Ar] 3d³; Zn²⁺ [Ar] 3d¹⁰."]], "3": [["Q4", "Water ligands split the 3d orbitals into two energy levels [1]; an electron absorbs a photon of orange/red light and is promoted to the higher level [1]; the remaining (complementary) light, blue, is transmitted and observed [1]."]], "4": [["Q5", "Zn²⁺ has a full 3d¹⁰ sublevel [1], so no electron can be promoted between split d-orbitals and no visible light is absorbed [1]."]], "6": [["Exit ticket", "Any three: variable oxidation states, coloured compounds, complex ions, catalytic activity, magnetism, high melting points."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f66ca062-89cc-5518-b2f2-dc876c3ae08a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S3.2' limit 1), 'S3.2 Functional groups: Classification of organic compounds · Lesson 1: Formulas, functional groups, homologous series, IUPAC names and structural isomers', 'IB DP Chemistry · S3.2 Functional groups: Classification of organic compounds', '/chem-s32-lesson1/', 'CHEM-S32-L1', 25, 16 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S32-L1', 'S3.2 Functional groups: Classification of organic compounds · Lesson 1: Formulas, functional groups, homologous series, IUPAC names and structural isomers', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Molecular", "Empirical", "Condensed structural", "Skeletal"], "tip": "How much detail?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Alcohol", "Aldehyde", "Ketone", "Carboxylic acid", "Ester", "Amine"], "tip": "Look at the functional group."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["more electrons", "larger", "chain", "surface"], ["london", "dispersion", "intermolecular"]], "tips": ["Type of IMF."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Propan-2-ol", "But-1-ene", "Butanoic acid", "Pentan-3-one", "2-methylpropane", "Methyl ethanoate"], "tip": "Count carbons; find the functional group."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Primary", "Secondary", "Tertiary", "Primary"], "tip": "Count C atoms on the C–OH carbon."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["general formula"], ["ch2", "differ by"], ["functional group", "similar chemical", "trend", "physical"]], "tips": ["Formula, difference, properties."]}]}, "models": {"1": [["Q1", "Molecular; empirical; condensed; skeletal."]], "2": [["Q2", "Alcohol; aldehyde; ketone; carboxylic acid; ester; amine."], ["Q3", "Longer molecules have more electrons and greater surface area [1], so London (dispersion) forces between molecules are stronger and need more energy to overcome [1]."]], "3": [["Q4", "Propan-2-ol; but-1-ene; butanoic acid; pentan-3-one; 2-methylpropane; methyl ethanoate."]], "4": [["Q5", "Primary; secondary; tertiary; primary."], ["Q6", "Butan-1-ol, butan-2-ol, 2-methylpropan-1-ol, 2-methylpropan-2-ol."]], "5": [["Q7", "Same general formula [1]; successive members differ by CH2 [1]; same functional group, so similar chemical properties and a gradual trend in physical properties [1]."]], "6": [["Exit ticket", "Propanal."]]}, "labels": {"q2_1": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '7fbf619d-b3d3-538a-9417-027e16e586ed', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'S3.2' limit 1), 'S3.2 Functional groups: Classification of organic compounds · Lesson 2 (HL): Stereoisomers, mass spectrometry, IR and ¹H NMR spectroscopy', 'IB DP Chemistry · S3.2 Functional groups: Classification of organic compounds', '/chem-s32-lesson2/', 'CHEM-S32-L2', 15, 17 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S32-L2', 'S3.2 Functional groups: Classification of organic compounds · Lesson 2 (HL): Stereoisomers, mass spectrometry, IR and ¹H NMR spectroscopy', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Cis–trans", "Optical", "None", "Optical", "Cis–trans"], "tip": "Two different groups on each C=C carbon? Four different groups on one C?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["C=O", "58", "Propanone"], "tip": "C=O and no O–H."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["3", "Triplet", "Quartet", "3 : 2 : 1"], "tip": "n + 1 from neighbours."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["carboxylic", "cooh", "o–h", "o-h"], ["c=o", "1710", "carbonyl"], ["propanoic", "ch3ch2cooh"]], "tips": ["Broad 2500–3000 + 1710 + δ 11.5."]}]}, "models": {"1": [["Q1", "But-2-ene and 1,2-dichloroethene: cis–trans. Butan-2-ol and lactic acid: optical. But-1-ene: none."]], "2": [["Q2", "C=O; M_r 58; propanone (CH₃COCH₃; fragment 43 = CH₃CO⁺)."]], "3": [["Q3", "3 signals; CH₃ triplet (2 neighbours); CH₂ quartet (3 neighbours); ratio 3 : 2 : 1 (OH singlet)."]], "4": [["Q4", "The very broad absorption at 2500–3000 cm⁻¹ shows the O–H of a carboxylic acid (and δ 11.5 is COOH) [1]; 1710 cm⁻¹ shows C=O [1]; three environments in ratio 3 : 2 : 1 fit propanoic acid, CH3CH2COOH [1]."]], "6": [["Exit ticket", "The ratio of hydrogen atoms in each environment."]]}, "labels": {"q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f74e7c93-ab19-502e-a8c9-3a2de1f20311', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R1.1' limit 1), 'R1.1 Measuring enthalpy changes · Lesson 1: Exothermic and endothermic reactions, energy profiles and calorimetry', 'IB DP Chemistry · R1.1 Measuring enthalpy changes', '/chem-r11-lesson1/', 'CHEM-R11-L1', 12, 18 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R11-L1', 'R1.1 Measuring enthalpy changes · Lesson 1: Exothermic and endothermic reactions, energy profiles and calorimetry', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Exothermic", "Endothermic", "Endothermic", "Exothermic", "Endothermic"], "tip": "Does the surroundings'' temperature rise?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["2842", "2.84", "q = 100"], ["0.0500", "0.05 mol"], ["−56.8", "-56.8", "−57", "-57"]], "tips": ["m = 100 g; n = 0.0500 mol."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["heat loss", "lost to", "surroundings", "incomplete"], ["insulat", "lid", "shield", "closer", "bomb"]], "tips": ["Where did the energy go?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["products", "lower enthalpy", "lower energy"], ["more stable", "stable"]], "tips": ["Compare reactants and products."]}]}, "models": {"1": [["Q1", "Combustion and neutralization: exothermic. Photosynthesis, dissolving NH₄NO₃ and decomposition: endothermic."]], "2": [["Q2", "Q = 100 × 4.18 × 6.8 = 2842 J [1]; n(H2O) = 0.0500 mol [1]; ΔH = −2.842 kJ ÷ 0.0500 = −56.8 kJ mol⁻¹ [1]."]], "3": [["Q3", "Heat is lost to the surroundings (and combustion may be incomplete) [1]; insulate the calorimeter, use a draught shield and lid, and place the flame closer to the can [1]."]], "4": [["Q4", "The products (CO2 and H2O) have lower enthalpy than the reactants [1], so they are more stable and energy is released to the surroundings [1]."]], "6": [["Exit ticket", "Q = mcΔT."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd97d1bb8-3c67-5f66-9529-fb13e0033046', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R1.2' limit 1), 'R1.2 Energy cycles in reactions · Lesson 1: Bond enthalpies and Hess''s law', 'IB DP Chemistry · R1.2 Energy cycles in reactions', '/chem-r12-lesson1/', 'CHEM-R12-L1', 7, 19 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R12-L1', 'R1.2 Energy cycles in reactions · Lesson 1: Bond enthalpies and Hess''s law', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["678", "862"], ["−184", "-184"]], "tips": ["Broken − formed."]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["average"], ["gas", "gaseous", "different compounds", "environment"]], "tips": ["What do the data assume?"]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["reverse", "+283", "283"], ["−111", "-111"]], "tips": ["Reverse the second equation."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 1, "pts": [["independent", "route", "path", "same"]], "tips": ["Route."]}]}, "models": {"1": [["Q1", "Bonds broken = 436 + 242 = 678 kJ; bonds formed = 2 × 431 = 862 kJ [1]; ΔH = 678 − 862 = −184 kJ mol⁻¹ [1]."], ["Q2", "Bond enthalpies are averages taken from many different compounds, not the actual molecules involved [1], and they apply only to the gaseous state [1]."]], "2": [["Q3", "Reverse the second reaction (ΔH = +283 kJ) and add to the first [1]: ΔH = −394 + 283 = −111 kJ mol⁻¹ [1]."]], "3": [["Q4", "The enthalpy change of a reaction is independent of the route taken, provided initial and final states are the same [1]."]], "6": [["Exit ticket", "Endothermic."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q2_0": "Q3", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '88e08b42-e5ff-55a0-9d42-f0783c1fb933', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R1.2' limit 1), 'R1.2 Energy cycles in reactions · Lesson 2 (HL): Enthalpies of formation and combustion, and Born–Haber cycles', 'IB DP Chemistry · R1.2 Energy cycles in reactions', '/chem-r12-lesson2/', 'CHEM-R12-L2', 6, 20 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R12-L2', 'R1.2 Energy cycles in reactions · Lesson 2 (HL): Enthalpies of formation and combustion, and Born–Haber cycles', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["−966", "-966", "products"], ["−892", "-892", "−890", "-890"]], "tips": ["Products − reactants; O₂ = 0."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["107 + 496 + 121", "375", "+ 411"], ["786", "+786"]], "tips": ["Sum of steps − ΔHf."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["1 mol", "one mole"], ["elements", "standard state", "standard conditions"]], "tips": ["Amount, from what, conditions."]}]}, "models": {"1": [["Q1", "ΣΔHf(products) = −394 + 2(−286) = −966 kJ [1]; ΔH = −966 − (−74) = −892 kJ mol⁻¹ [1]."]], "2": [["Q2", "ΔH_lattice = 107 + 496 + 121 + (−349) − (−411) [1] = +786 kJ mol⁻¹ [1]."]], "3": [["Q3", "The enthalpy change when one mole of a compound is formed [1] from its elements in their standard states under standard conditions [1]."]], "6": [["Exit ticket", "Zero (element in its standard state)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
