insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R13-L1', 'R1.3 Energy from fuels · Lesson 1: Combustion, fossil fuels, biofuels and fuel cells', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["13", "Carbon monoxide", "Carbon (soot)"], "tip": "Balance C, H, then O."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["renewable", "carbon neutral", "photosynthesis", "absorb"], ["land", "food", "deforest", "lower energy", "fertiliser"], ["conclusion", "overall", "depends"]], "tips": ["Strength, weakness, judgement."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["water", "no co2", "no pollutant"], ["efficien", "directly", "less heat"]], "tips": ["Products and efficiency."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["carbon monoxide", "co", "toxic", "haemoglobin"], ["soot", "carbon", "less energy", "particulate"]], "tips": ["Products and energy."]}]}, "models": {"1": [["Q1", "2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O; CO is toxic; soot is carbon."]], "2": [["Q2", "Bioethanol is renewable and the CO₂ released was recently absorbed by photosynthesis, so it is closer to carbon-neutral [1]; however growing crops uses land that could grow food, may cause deforestation, and bioethanol has a lower specific energy [1]; overall it is more sustainable only if crops are grown on waste land or from waste biomass [1]."]], "3": [["Q3", "The only product is water, so no CO₂ or pollutants are emitted at the point of use [1]; it converts chemical energy directly to electricity more efficiently, with less energy wasted as heat [1]."]], "4": [["Q4", "It produces toxic carbon monoxide, which binds to haemoglobin [1], and soot particles that harm lungs, while releasing less energy than complete combustion [1]."]], "6": [["Exit ticket", "2H₂ + O₂ → 2H₂O."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '86dbfb7d-5cd6-59e4-85a0-117b0fc7c82d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R1.4' limit 1), 'R1.4 Entropy and spontaneity · Lesson 1 (HL): Entropy, Gibbs energy and spontaneity', 'IB DP Chemistry · R1.4 Entropy and spontaneity', '/chem-r14-lesson1/', 'CHEM-R14-L1', 12, 22 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R14-L1', 'R1.4 Entropy and spontaneity · Lesson 1 (HL): Entropy, Gibbs energy and spontaneity', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Positive", "Negative", "Positive", "Negative"], "tip": "Count gas moles; states."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["0.161", "48"], ["+130", "130"], ["1106", "1110", "1105"]], "tips": ["Convert ΔS to kJ."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["ΔG = 0", "K > 1", "ΔG < 0"], "tip": "ΔG⦵ = −RT ln K."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["−tδs", "-tδs", "tδs", "positive", "t δs"], ["larger than", "outweigh", "exceed", "δg positive", "becomes positive"]], "tips": ["Size of TΔS at high T."]}]}, "models": {"1": [["Q1", "Evaporation and decomposition releasing gas: positive. Fewer gas moles and precipitation: negative."]], "2": [["Q2", "ΔG = 178 − 298 × 0.161 = 178 − 48.0 [1] = +130 kJ mol⁻¹, not spontaneous [1]; T = 178 ÷ 0.161 = 1106 K [1]."]], "3": [["Q3", "Equilibrium: ΔG = 0; negative ΔG⦵ gives K > 1; spontaneous: ΔG < 0."]], "4": [["Q4", "With ΔS negative, the term −TΔS is positive and grows with temperature [1]; at high temperature it outweighs the negative ΔH, so ΔG becomes positive [1]."]], "6": [["Exit ticket", "ΔG = ΔH − TΔS."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '72e4e0da-f700-54c0-86e7-7ebb4c7ef8c5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R2.1' limit 1), 'R2.1 How much? The amount of chemical change · Lesson 1: Equations, reacting quantities, limiting reactants, yield and atom economy', 'IB DP Chemistry · R2.1 How much? The amount of chemical change', '/chem-r21-lesson1/', 'CHEM-R21-L1', 16, 23 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R21-L1', 'R2.1 How much? The amount of chemical change · Lesson 1: Equations, reacting quantities, limiting reactants, yield and atom economy', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.100 mol", "0.0500 mol", "4.03 g", "1.14 dm³"], "tip": "Mole ratio 2 : 1 : 2."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 3, "pts": [["0.00200", "2.00 × 10"], ["0.00400", "4.00 × 10", "× 2", "x 2"], ["0.160"]], "tips": ["2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["0.0895", "0.156"], ["iron", "fe is limiting", "fe limiting"], ["7.87", "7.9"]], "tips": ["Compare moles 1 : 1."]}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 2, "n": 2, "ans": ["80.1%", "Product lost during filtration"], "tip": "Experimental ÷ theoretical × 100."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["92.16", "2 × 46", "92.2"], ["51.1", "51"]], "tips": ["Two ethanol molecules form."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["yield+experimental", "yield+actual", "yield+obtained"], ["atom economy+equation", "atom economy+reactants", "atom economy+desired product", "atom economy+waste"]], "tips": ["Measured vs calculated from equation."]}]}, "models": {"1": [["Q1", "0.100 mol Mg; 0.0500 mol O₂; 0.100 × 40.31 = 4.03 g MgO; 0.0500 × 22.7 = 1.14 dm³."], ["Q2", "n(H₂SO₄) = 0.100 × 0.0200 = 0.00200 mol [1]; n(NaOH) = 2 × 0.00200 = 0.00400 mol [1]; c = 0.00400 ÷ 0.0250 = 0.160 mol dm⁻³ [1]."]], "2": [["Q3", "n(Fe) = 0.0895 mol; n(S) = 0.156 mol [1]; iron is limiting [1]; mass FeS = 0.0895 × 87.92 = 7.87 g [1]."], ["Q4", "6.30 ÷ 7.87 × 100 = 80.1%; losses during transfer and filtration."]], "3": [["Q5", "Mass of desired product = 2 × 46.08 = 92.16 [1]; atom economy = 92.16 ÷ 180.18 × 100 = 51.1% [1]."]], "4": [["Q6", "Percentage yield compares the actual mass of product obtained with the theoretical maximum [1]; atom economy compares the mass of the desired product with the total mass of reactants in the balanced equation, showing how much becomes waste [1]."]], "6": [["Exit ticket", "The limiting reactant."]]}, "labels": {"q1_1": "Q2", "q2_0": "Q3", "q3_0": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '1e139769-6dd6-537f-81b4-57a880229ca5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R2.2' limit 1), 'R2.2 How fast? The rate of chemical change · Lesson 1: Measuring rates, collision theory, factors, activation energy and catalysts', 'IB DP Chemistry · R2.2 How fast? The rate of chemical change', '/chem-r22-lesson1/', 'CHEM-R22-L1', 12, 24 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R22-L1', 'R2.2 How fast? The rate of chemical change · Lesson 1: Measuring rates, collision theory, factors, activation energy and catalysts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Gas syringe", "Mass loss on a balance", "Disappearing cross", "Colorimeter"], "tip": "What changes that can be measured?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["kinetic energy", "faster", "move"], ["more frequent", "frequency", "collide more"], ["activation energy", "greater proportion", "more particles have", "e ≥ ea"]], "tips": ["Two effects; which is bigger?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["alternative", "pathway", "route"], ["lower", "activation energy"], ["more particles", "greater proportion", "area", "successful"]], "tips": ["Ea line moves."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["surface area", "exposed"], ["frequent", "frequency"]], "tips": ["Surface area and collisions."]}]}, "models": {"1": [["Q1", "Gas syringe; mass loss; disappearing cross; colorimeter."]], "2": [["Q2", "Particles have more kinetic energy and move faster [1], so they collide more frequently [1]; more importantly, a greater proportion of collisions have energy equal to or greater than the activation energy [1]."]], "3": [["Q3", "A catalyst provides an alternative reaction pathway [1] with lower activation energy [1]; so a greater proportion of particles (larger area under the curve) have energy ≥ Ea and more collisions are successful [1]."]], "4": [["Q4", "Powder has a larger surface area, so more particles are exposed to the acid [1], giving more frequent collisions [1]."]], "6": [["Exit ticket", "Energy ≥ activation energy and correct orientation."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'fa989833-686f-5da3-85a1-e454c4772d83', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R2.2' limit 1), 'R2.2 How fast? The rate of chemical change · Lesson 2 (HL): Mechanisms, rate equations, orders, rate constants and the Arrhenius equation', 'IB DP Chemistry · R2.2 How fast? The rate of chemical change', '/chem-r22-lesson2/', 'CHEM-R22-L2', 13, 25 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R22-L2', 'R2.2 How fast? The rate of chemical change · Lesson 2 (HL): Mechanisms, rate equations, orders, rate constants and the Arrhenius equation', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["NO₃", "Step 1", "Bimolecular"], "tip": "Formed then used = intermediate."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["First", "Second", "Third", "2.0 mol⁻² dm⁶ s⁻¹"], "tip": "Compare experiments changing one concentration."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["two no2", "2no2", "no2 + no2", "step 1"], ["co not", "not in", "fast step", "after", "rate-determining"]], "tips": ["Which species are in the slow step?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["8.31", "−ea/r", "-ea/r", "gradient"], ["49.9", "50"]], "tips": ["Ea = −gradient × R."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["mechanism", "steps", "elementary"], ["rate-determining", "slowest", "experiment"]], "tips": ["Mechanism."]}]}, "models": {"1": [["Q1", "NO₃ is the intermediate; step 1 is rate-determining and bimolecular."]], "2": [["Q2", "A first order (rate ×2), B second order (rate ×4), overall third; k = 2.0 × 10⁻³ ÷ (0.10 × 0.10²) = 2.0 mol⁻² dm⁶ s⁻¹."], ["Q3", "The slow, rate-determining step involves two NO₂ molecules, matching second order in NO₂ [1]; CO reacts only in the fast step after the RDS, so it does not appear in the rate equation [1]."]], "3": [["Q4", "Gradient = −Ea/R, so Ea = 6000 × 8.31 [1] = 49 860 J mol⁻¹ = 49.9 kJ mol⁻¹ [1]."]], "4": [["Q5", "Most reactions occur in several elementary steps [1]; the rate depends on the slowest (rate-determining) step, which can only be found by experiment [1]."]], "6": [["Exit ticket", "s⁻¹."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '2d2d99f6-732c-54c7-a1c0-0cec3a139ae3', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R2.3' limit 1), 'R2.3 How far? The extent of chemical change · Lesson 1: Dynamic equilibrium, the equilibrium law and Le Châtelier''s principle', 'IB DP Chemistry · R2.3 How far? The extent of chemical change', '/chem-r23-lesson1/', 'CHEM-R23-L1', 13, 26 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R23-L1', 'R2.3 How far? The extent of chemical change · Lesson 1: Dynamic equilibrium, the equilibrium law and Le Châtelier''s principle', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["rate", "equal"], ["concentration", "constant", "closed"]], "tips": ["Rates and concentrations."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["[NH₃]² / [N₂][H₂]³", "Products favoured", "Temperature only"], "tip": "Products over reactants."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Increases", "Decreases", "No change", "Increases"], "tip": "Fewer gas moles on the right; exothermic forward."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["rate", "slow", "too slow"], ["compromise", "acceptable", "balance"]], "tips": ["Rate vs yield."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["no effect", "no change", "does not change", "position"], ["both", "equally", "faster", "rate"]], "tips": ["Forward and backward."]}]}, "models": {"1": [["Q1", "The rates of the forward and backward reactions are equal [1]; the concentrations of reactants and products remain constant (in a closed system) [1]."]], "2": [["Q2", "K = [NH₃]²/[N₂][H₂]³; large K: products favoured; only temperature changes K."]], "3": [["Q3", "Pressure ↑: increases; temperature ↑: decreases (endothermic direction); catalyst: no change; removing NH₃: increases."], ["Q4", "At low temperatures the rate of reaction would be far too slow [1], so 450 °C is a compromise giving an acceptable yield at a reasonable rate [1]."]], "4": [["Q5", "A catalyst does not change the position of equilibrium or K [1] because it increases the rates of the forward and backward reactions equally, so equilibrium is reached faster [1]."]], "6": [["Exit ticket", "Temperature."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ab4dbfe5-5496-57a6-9ba9-baa625253ec6', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R2.3' limit 1), 'R2.3 How far? The extent of chemical change · Lesson 2 (HL): Reaction quotient, equilibrium calculations and K and ΔG', 'IB DP Chemistry · R2.3 How far? The extent of chemical change', '/chem-r23-lesson2/', 'CHEM-R23-L2', 10, 27 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R23-L2', 'R2.3 How far? The extent of chemical change · Lesson 2 (HL): Reaction quotient, equilibrium calculations and K and ΔG', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Forward (right)", "Backward (left)", "At equilibrium"], "tip": "Compare Q and K."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["0.78", "x = 0.78"], ["0.22"], ["50", "50.3", "50.2"]], "tips": ["2x = 1.56."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["4.04", "ln k", "10000"], ["56.6", "57"]], "tips": ["ln K = −ΔG/RT."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["q < k", "q less", "forward", "right"], ["q > k", "q greater", "backward", "left", "reverse"]], "tips": ["Two cases."]}]}, "models": {"1": [["Q1", "Q < K forward; Q > K backward; Q = K equilibrium."]], "2": [["Q2", "x = 0.78, so [H₂] = [I₂] = 1.00 − 0.78 = 0.22 mol dm⁻³ [1] [1]; K = 1.56² ÷ (0.22 × 0.22) = 50.3 [1]."]], "3": [["Q3", "ln K = 10 000 ÷ (8.31 × 298) = 4.04 [1]; K = e^4.04 = 56.6 [1]."]], "4": [["Q4", "If Q < K there are too few products, so the reaction proceeds forward [1]; if Q > K there are too many products, so it proceeds backward until Q = K [1]."]], "6": [["Exit ticket", "The reaction will shift backward (to the left) to reach equilibrium."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6c017e99-424d-5c7e-a67b-878b6cb8e3b0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.1' limit 1), 'R3.1 Proton transfer reactions · Lesson 1: Brønsted–Lowry acids and bases, pH, Kw, strong and weak acids, neutralization and pH curves', 'IB DP Chemistry · R3.1 Proton transfer reactions', '/chem-r31-lesson1/', 'CHEM-R31-L1', 16, 28 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R31-L1', 'R3.1 Proton transfer reactions · Lesson 1: Brønsted–Lowry acids and bases, pH, Kw, strong and weak acids, neutralization and pH curves', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["H₂O", "NH₃", "NH₄⁺", "OH⁻"], "tip": "Follow the H⁺."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["2", "1", "1.0 × 10⁻³", "12"], "tip": "For NaOH, [H⁺] = Kw ÷ [OH⁻]."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["ph", "conductivity"], ["rate", "magnesium", "carbonate", "bubbles", "faster"]], "tips": ["Measure [H⁺] effects."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Salt + water", "Salt + water", "Salt + water + carbon dioxide", "Salt + water + carbon dioxide"], "tip": "Carbonates give CO₂."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["strong+complete", "strong+fully"], ["weak+partial", "weak+partly", "weak+equilibrium"]], "tips": ["Extent of ionization."]}]}, "models": {"1": [["Q1", "H₂O donates H⁺ (acid); NH₃ accepts (base); NH₄⁺ is its conjugate acid; OH⁻ is the conjugate base of water."]], "2": [["Q2", "pH 2; pH 1; 1.0 × 10⁻³ mol dm⁻³; [H⁺] = 10⁻¹⁴/10⁻² = 10⁻¹² → pH 12."]], "3": [["Q3", "Measure pH: HCl has the lower pH (or higher electrical conductivity) [1]; add magnesium or a carbonate: HCl reacts faster, producing gas more rapidly [1]."]], "4": [["Q4", "Hydroxides and oxides: salt + water. Carbonates and hydrogencarbonates: salt + water + CO₂."]], "5": [["Q5", "A strong acid ionizes (dissociates) completely in water [1]; a weak acid only partially ionizes, setting up an equilibrium [1]."]], "6": [["Exit ticket", "pH = 3."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '051c5895-50c9-5f40-8d44-063429a3987f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.1' limit 1), 'R3.1 Proton transfer reactions · Lesson 2 (HL): pOH, Ka and Kb, salt hydrolysis, pH curves, indicators and buffers', 'IB DP Chemistry · R3.1 Proton transfer reactions', '/chem-r31-lesson2/', 'CHEM-R31-L2', 15, 29 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R31-L2', 'R3.1 Proton transfer reactions · Lesson 2 (HL): pOH, Ka and Kb, salt hydrolysis, pH curves, indicators and buffers', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["1.34 × 10", "1.3 × 10", "√", "sqrt"], ["2.87", "2.9"]], "tips": ["[H⁺] = √(Ka × c)."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Basic", "Acidic", "Neutral", "Basic"], "tip": "Parent acid and base strengths."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Phenolphthalein", "Methyl orange", "No suitable indicator"], "tip": "Where is the steep section?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["oh⁻", "oh-", "hydroxide"], ["ch3cooh", "ethanoic acid", "react", "removed", "water"]], "tips": ["Which component reacts with OH⁻?"]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["log", "0.30", "2"], ["5.06", "5.1"]], "tips": ["pH = pKa + log(salt/acid)."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["half", "half-equivalence", "half-neutral"], ["[ha] = [a⁻]", "equal", "ph = pka", "ph equals pka"]], "tips": ["Half the volume to equivalence."]}]}, "models": {"1": [["Q1", "[H⁺] = √(1.8 × 10⁻⁵ × 0.100) = 1.34 × 10⁻³ mol dm⁻³ [1]; pH = 2.87 [1]."]], "2": [["Q2", "Sodium ethanoate and sodium carbonate: basic. Ammonium chloride: acidic. KNO₃: neutral."]], "3": [["Q3", "Phenolphthalein (equivalence above 7); methyl orange (below 7); weak–weak has no sharp change."]], "4": [["Q4", "The added hydroxide ions react with ethanoic acid molecules [1]: CH3COOH + OH⁻ → CH3COO⁻ + H2O, removing OH⁻ so the pH changes very little [1]."], ["Q5", "pH = 4.76 + log(0.20 ÷ 0.10) = 4.76 + 0.30 [1] = 5.06 [1]."]], "5": [["Q6", "Find the pH at the half-equivalence point (half the volume of base needed for equivalence) [1]; here [HA] = [A⁻], so pH = pKa [1]."]], "6": [["Exit ticket", "Ka × Kb = Kw."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '53ae0348-af43-5ad6-829f-9afb5635add8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.2' limit 1), 'R3.2 Electron transfer reactions · Lesson 1: Oxidation and reduction, half-equations, reactivity, primary, secondary and electrolytic cells', 'IB DP Chemistry · R3.2 Electron transfer reactions', '/chem-r32-lesson1/', 'CHEM-R32-L1', 16, 30 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R32-L1', 'R3.2 Electron transfer reactions · Lesson 1: Oxidation and reduction, half-equations, reactivity, primary, secondary and electrolytic cells', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Zn", "Cu²⁺", "Cu²⁺", "Zn"], "tip": "Who loses electrons?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Yes", "No", "Yes", "No"], "tip": "Activity series."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["zinc", "zn"], ["ions", "flow", "move"], ["neutral", "balance", "charge", "complete"]], "tips": ["Where is oxidation? What carries charge in solution?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Lead", "Bromine", "Anode"], "tip": "Cations to the cathode."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["voltaic+chemical", "voltaic+spontaneous"], ["electrolytic+electrical", "electrolytic+non-spontaneous"]], "tips": ["Energy conversion and spontaneity."]}]}, "models": {"1": [["Q1", "Zn is oxidized (reducing agent); Cu²⁺ is reduced (oxidizing agent)."]], "2": [["Q2", "Zn + HCl: yes. Cu + acid: no. Fe + CuSO₄: yes. Ag + ZnSO₄: no."]], "3": [["Q3", "Zinc is the anode, where oxidation occurs [1]; the salt bridge allows ions to move between the half-cells [1], maintaining electrical neutrality and completing the circuit [1]."]], "4": [["Q4", "Lead at the cathode; bromine at the anode; oxidation at the anode."]], "5": [["Q5", "A voltaic cell converts chemical energy to electrical energy from a spontaneous reaction [1]; an electrolytic cell uses electrical energy to drive a non-spontaneous reaction [1]."]], "6": [["Exit ticket", "The anode."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '9f53fff7-476f-5d75-9958-a9821413b8e1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.2' limit 1), 'R3.2 Electron transfer reactions · Lesson 2: Oxidation and reduction of organic compounds', 'IB DP Chemistry · R3.2 Electron transfer reactions', '/chem-r32-lesson2/', 'CHEM-R32-L2', 12, 31 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R32-L2', 'R3.2 Electron transfer reactions · Lesson 2: Oxidation and reduction of organic compounds', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ethanal", "Ethanoic acid", "Propanone", "No reaction"], "tip": "Primary, secondary or tertiary?"}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["aldehyde", "ethanal", "volatile", "escape"], ["condens", "return", "further oxid", "complete"]], "tips": ["What would happen to ethanal?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Propan-2-ol", "Propan-1-ol", "Ethane", "Ethanol"], "tip": "Ketone → secondary alcohol."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["orange", "green"], ["tertiary", "no change", "stays orange", "not oxidized"]], "tips": ["Secondary vs tertiary."]}]}, "models": {"1": [["Q1", "Ethanal; ethanoic acid; propanone; no reaction (tertiary)."], ["Q2", "Ethanal is volatile and would escape [1]; refluxing condenses vapours back into the flask so the aldehyde is further oxidized to the carboxylic acid [1]."]], "2": [["Q3", "Propan-2-ol; propan-1-ol; ethane; ethanol."]], "3": [["Q4", "Propan-2-ol (secondary) is oxidized, turning the dichromate from orange to green [1]; 2-methylpropan-2-ol (tertiary) is not oxidized, so it stays orange [1]."]], "6": [["Exit ticket", "A ketone."]]}, "labels": {"q1_1": "Q2", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f6f0a6e0-8a7c-5514-9bff-1b0d7c63a31f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.2' limit 1), 'R3.2 Electron transfer reactions · Lesson 3 (HL): Standard electrode potentials, cell potentials, ΔG and electrolysis of aqueous solutions', 'IB DP Chemistry · R3.2 Electron transfer reactions', '/chem-r32-lesson3/', 'CHEM-R32-L3', 11, 32 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R32-L3', 'R3.2 Electron transfer reactions · Lesson 3 (HL): Standard electrode potentials, cell potentials, ΔG and electrolysis of aqueous solutions', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["1.10", "+1.10", "0.34 − (−0.76)", "0.34 - (-0.76)"], ["spontaneous", "positive"]], "tips": ["Cathode − anode."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2 × 96 500", "96500", "−nfe"], ["−212", "-212"]], "tips": ["Convert to kJ."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Hydrogen", "Chlorine", "Copper", "Oxygen"], "tip": "Compare E⦵ with water."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["spoon+cathode"], ["silver+anode"], ["electrolyte", "ag⁺", "ag+", "silver nitrate", "silver ions"]], "tips": ["Cathode, anode, electrolyte."]}]}, "models": {"1": [["Q1", "E⦵cell = 0.34 − (−0.76) = +1.10 V [1]; positive, so the reaction is spontaneous [1]."]], "2": [["Q2", "ΔG⦵ = −2 × 96 500 × 1.10 [1] = −212 300 J = −212 kJ mol⁻¹ [1]."]], "3": [["Q3", "Brine: H₂ at cathode, Cl₂ at anode. CuSO₄: Cu at cathode, O₂ at anode."]], "4": [["Q4", "Make the spoon the cathode [1], a silver bar the anode [1], and use an electrolyte containing silver ions, such as silver nitrate solution [1]."]], "6": [["Exit ticket", "The reaction is spontaneous (ΔG⦵ negative)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '54e73dfb-862d-5617-97a8-c883409797c1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.3' limit 1), 'R3.3 Electron sharing reactions · Lesson 1: Radicals, homolytic fission and radical substitution of alkanes', 'IB DP Chemistry · R3.3 Electron sharing reactions', '/chem-r33-lesson1/', 'CHEM-R33-L1', 8, 33 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R33-L1', 'R3.3 Electron sharing reactions · Lesson 1: Radicals, homolytic fission and radical substitution of alkanes', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["one electron", "each", "equally"], ["radical", "uv"]], "tips": ["How are the electrons shared out?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Initiation", "Propagation", "Termination", "Propagation"], "tip": "Radicals made, kept, or removed?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["further substitution", "more h", "replaced", "ch2cl2", "chcl3"], ["radical", "termination", "ethane", "c2h6"]], "tips": ["Further reactions and terminations."]}]}, "models": {"1": [["Q1", "The Cl–Cl bond breaks so that each chlorine atom takes one of the bonding electrons [1], forming two chlorine radicals, initiated by UV light [1]."]], "2": [["Q2", "Initiation; propagation; termination; propagation."]], "3": [["Q3", "Chlorine radicals can substitute further hydrogen atoms, giving CH2Cl2, CHCl3 and CCl4 [1]; termination steps such as two methyl radicals combining also produce ethane [1]."]], "6": [["Exit ticket", "UV light (to cause homolytic fission of Cl₂)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
