insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R34-L1', 'R3.4 Electron-pair sharing reactions · Lesson 1: Nucleophiles, electrophiles, heterolytic fission, substitution and electrophilic addition', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Nucleophile", "Nucleophile", "Not a nucleophile", "Nucleophile", "Not a nucleophile"], "tip": "Electron-pair donor?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["homolytic+one", "homolytic+each", "homolytic+radical"], ["heterolytic+both", "heterolytic+ion", "heterolytic+one fragment"]], "tips": ["Where do the electrons go?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["1,2-dibromoethane", "Bromoethane", "Ethanol", "Ethane"], "tip": "Add across the double bond."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["double bond", "π", "pi"], ["electron density", "electron-rich", "attract"]], "tips": ["Electron density."]}]}, "models": {"1": [["Q1", "OH⁻, NH₃, CN⁻: nucleophiles. H⁺ and Br₂ accept electrons (electrophiles)."]], "2": [["Q2", "In homolytic fission each atom takes one bonding electron, forming radicals [1]; in heterolytic fission one atom takes both electrons, forming ions [1]."]], "3": [["Q3", "1,2-dibromoethane; bromoethane; ethanol; ethane."]], "4": [["Q4", "The C=C double bond (π bond) [1] is a region of high electron density that attracts electrophiles [1]."]], "6": [["Exit ticket", "Orange to colourless."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '92789f81-e6fc-549b-87ed-8d44578d7af5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'ib-chemistry' and t.code = 'R3.4' limit 1), 'R3.4 Electron-pair sharing reactions · Lesson 2 (HL): Lewis acids and bases, complex ions, SN1 and SN2, electrophilic addition mechanisms and Markovnikov''s rule', 'IB DP Chemistry · R3.4 Electron-pair sharing reactions', '/chem-r34-lesson2/', 'CHEM-R34-L2', 18, 35 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R34-L2', 'R3.4 Electron-pair sharing reactions · Lesson 2 (HL): Lewis acids and bases, complex ions, SN1 and SN2, electrophilic addition mechanisms and Markovnikov''s rule', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Lewis acid", "Lewis base", "Lewis acid", "Lewis base", "Lewis acid"], "tip": "Accepts or donates a pair?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["SN2", "SN1", "SN2", "SN1", "SN2"], "tip": "Primary → SN2; tertiary → SN1."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["c–i", "c-i", "weaker", "bond enthalpy"], ["break", "easier", "leaving group"]], "tips": ["Bond strength."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["2-bromopropane", "1-bromopropane", "Secondary carbocation"], "tip": "More alkyl groups stabilize the carbocation."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["secondary carbocation", "secondary"], ["stable", "inductive", "alkyl", "electron-releasing"], ["more likely", "major", "forms preferentially", "bromide attacks"]], "tips": ["Carbocation stability."]}]}, "models": {"1": [["Q1", "BF₃, Fe³⁺, AlCl₃: Lewis acids. NH₃ and H₂O ligands: Lewis bases."]], "2": [["Q2", "Primary and second-order, inversion: SN2. Tertiary and carbocation: SN1."], ["Q3", "The C–I bond has a lower bond enthalpy (is weaker) than the C–Cl bond [1], so it breaks more easily and iodide is a better leaving group [1]."]], "3": [["Q4", "Major 2-bromopropane via the more stable secondary carbocation; minor 1-bromopropane."]], "4": [["Q5", "Addition of H⁺ to the terminal carbon forms a secondary carbocation [1], which is more stable than a primary carbocation because of the positive inductive effect of the two alkyl groups [1]; so it forms preferentially and bromide attacks it, giving 2-bromopropane as the major product [1]."]], "6": [["Exit ticket", "SN2."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
